  ui_story_32180601_1_15_dialog_content = "Odeio repetir, mas não sou o dono deste lugar.",
  ui_story_32180601_1_16_dialog_content = "Seu caráter humilde é admirável, senhor. Não há dúvida sobre isso.",
  ui_story_32180601_1_17_dialog_content = "De acordo com o documento da Sra. Sheol, você é o único curador aqui.",
