  ui_story_32180601_1_21_dialog_content = "<color=#e8d9bb>Caro PlayerName, faz um tempo desde a última vez que falamos, espero que esteja bem.</color>",
  ui_story_32180601_1_22_dialog_content = "<color=#e8d9bb>Com a expansão da Guilda Cloudrover, tenho um assunto importante para discutir com você.</color>",
  ui_story_32180601_1_23_dialog_content = "<color=#e8d9bb>Eu ficaria grato se você pudesse encontrar tempo para se encontrar comigo. Aguardo ansiosamente para ouvir de você.</color>",
  ui_story_32180601_1_24_dialog_content = "<color=#e8d9bb>Com amor, Sheol</color>",
  ui_story_32180601_1_25_dialog_content = "O papel de carta sofisticado e o selo de cera por si só gritam luxo.",
  ui_story_32180601_1_26_dialog_content = "Mas esse convite, do nada, me deu um mau pressentimento.",
  ui_story_32180601_1_27_dialog_content = "E a Senhora Sheol gosta de provocar as pessoas. Ainda assim, diz que é um assunto importante.",
  ui_story_32180601_1_28_dialog_content = "A expedição conjunta ainda está em andamento, e não podemos dispensar a ajuda da Senhora Sheol.",
  ui_story_32180601_1_29_dialog_content = "Acho que terei que ir.",
  ui_story_32180601_1_30_dialog_content = "Então este é o novo clube que a Senhora Sheol acabou de adquirir?",
  ui_story_32180601_1_31_dialog_content = "Isso não é um pouco... muito luxuoso? Para que é destinado?",
  ui_story_32180601_1_32_dialog_content = "Como assim?",
  ui_story_32180601_1_33_dialog_content = "Ah, desculpe, não estou tentando ser intrometido. A Senhora Sheol me convidou.",
