  ui_story_32180601_1_35_dialog_content = "A Senhora Sheol tem estado à sua espera há algum tempo, mas... por que você está vestido assim?",
  ui_story_32180601_1_36_dialog_content = "Hã? Eu pensei que deveria me vestir para uma ocasião assim.",
  ui_story_32180601_1_37_dialog_content = "Claro. Por favor, siga-me.",
  ui_story_32180601_1_38_dialog_content = "Beleza!",
  ui_story_32180601_1_39_dialog_content = "Este é o lugar.",
  ui_story_32180601_1_40_dialog_content = "A-Tem certeza?",
  ui_story_32180601_1_41_dialog_content = "Isso mesmo, a Senhora Sheol me instruiu para escoltá-lo aqui após sua chegada.",
  ui_story_32180601_1_42_dialog_content = "Achei que você viria de roupão.",
  ui_story_32180601_1_43_dialog_content = "(Um banho luxuoso... O que está acontecendo...)",
  ui_story_32180601_1_44_dialog_content = "Hmm, talvez eu devesse apenas—",
  ui_story_32180601_1_45_dialog_content = "PlayerName, minha querida, você finalmente está aqui.",
  ui_story_32180601_1_46_dialog_content = "Você poderia, por favor, não me deixar esperando aqui por mais tempo?",
  ui_story_32180601_1_47_dialog_content = "M-May Posso entrar?",
  ui_story_32180601_1_48_dialog_content = "Não vejo nada de errado nisso. Estamos aqui para discutir assuntos de negócios, não estamos?",
  ui_story_32180601_1_49_dialog_content = "Entre.",
  ui_story_32180601_1_50_dialog_content = "Eu... Eu entendi agora!",
  ui_story_32180601_1_51_dialog_content = "O vapor está tão espesso... Mal consigo ver qualquer coisa.",
  ui_story_32180601_1_52_dialog_content = "Que decepção. Por que você está vestido tão formalmente? Eu estava esperando convidá-lo para tomar um banho juntos.",
  ui_story_32180601_1_53_dialog_content = "O quê?!",
  ui_story_32180601_1_54_dialog_content = "Tão tímida que você correu para fora, que adorável, minha querida.",
  ui_story_32180601_1_55_dialog_content = "Não mencionei no convite? Estou particularmente ansioso pela sua chegada.",
  ui_story_32180601_1_56_dialog_content = "Mas, mas quem teria pensado que seria em um banho público?",
  ui_story_32180601_1_57_dialog_content = "Isso é apenas uma parte do clube, meu querido. Por que você parece tão surpreso? Estou devidamente vestida. Gostaria de verificar?",
  ui_story_32180601_1_58_dialog_content = "O banho tem 19 ervas diferentes nele, e a água está sempre na temperatura certa.",
  ui_story_32180601_1_59_dialog_content = "Como meu convidado mais estimado, seu feedback é inestimável.",
  ui_story_32180601_1_60_dialog_content = "Certo! Vamos fazer a empregada principal trazer-lhe um roupão de banho. Gostaria de me acompanhar?",
  ui_story_32180601_1_61_option_content = "Por que não... falamos de negócios primeiro?",
  ui_story_32180601_1_62_dialog_content = "Hehe, você realmente é impaciente...",
  ui_story_32180601_1_63_dialog_content = "Mas eu realmente gosto dessa sede por oportunidades de negócios.",
  ui_story_32180601_1_64_option_content = "Por favor, pare de me provocar...",
  ui_story_32180601_1_65_dialog_content = "Acredito que isso ainda faz parte dos nossos negócios.",
  ui_story_32180601_1_66_dialog_content = "Mas você parece tão vermelho. Talvez este não seja o melhor lugar para você.",
  ui_story_32180601_1_67_dialog_content = "Você pode ir ao salão primeiro. Estarei lá em um minuto para discutir o nosso assunto em mãos, o verdadeiro assunto.",
  ui_story_32180601_1_68_dialog_content = "Você tem certeza de que é um assunto de negócios, certo?",
  ui_story_32180601_1_69_dialog_content = "Claro, e é algo que vai te beneficiar muito. Você pode muito bem esperar por isso.",
  ui_story_32180601_1_70_dialog_content = "Há algo em que eu possa ajudar? Esta é a sua terceira xícara de chá.",
  ui_story_32180601_1_71_dialog_content = "Estou bem...",
  ui_story_32180601_1_72_dialog_content = "E suas bochechas continuam vermelhas.",
  ui_story_32180601_1_73_dialog_content = "Você poderia diminuir o ar condicionado para mim? Obrigado.",
  ui_story_32180601_1_74_dialog_content = "<color=#e8d9bb>Creee...</color>",
  ui_story_32180601_1_75_dialog_content = "Peço desculpas pela espera, minha querida.",
  ui_story_32180601_1_76_dialog_content = "Aqui está você, quanto tempo você passou—",
  ui_story_32180601_1_77_dialog_content = "Eu só quero me arrumar para combinar com o seu traje.",
  ui_story_32180601_1_78_dialog_content = "Levou algum tempo.",
  ui_story_32180601_1_79_dialog_content = "Nossa, o vestido...",
  ui_story_32180601_1_80_dialog_content = "Você é deslumbrante todos os dias, mas esse vestido...",
  ui_story_32180601_1_81_dialog_content = "Bem? Isso é bom o suficiente para você?",
  ui_story_32180601_1_82_dialog_content = "Pare de brincar... Não é uma questão de ser bom o suficiente ou não. Eu me sinto envergonhado agora.",
  ui_story_32180601_1_83_dialog_content = "Não diga isso, Sr. Navegador, afinal, você é o dono aqui.",
  ui_story_32180601_1_84_dialog_content = "Eu sou o... dono?",
  ui_story_32180601_1_85_dialog_content = "Isso mesmo, te convidei aqui hoje para transferir a propriedade deste clube para o seu cuidado.",
  ui_story_32180601_1_86_dialog_content = "Pfttt—Desculpe, tosse, tosse... O que foi isso?!",
  ui_story_32180601_1_87_dialog_content = "Como meu cliente mais valioso, é justo te oferecer algo.",
  ui_story_32180601_1_88_dialog_content = "Isso não é apenas algo!",
  ui_story_32180601_1_89_dialog_content = "Se você não pode explicar, eu absolutamente não aceitarei...",
  ui_story_32180601_1_90_dialog_content = "Claro—eu tinha meus motivos.",
  ui_story_32180601_1_91_dialog_content = "Este clube sofisticado pertencia ao meu rival, um chefe do mercado negro.",
  ui_story_32180601_1_92_dialog_content = "Assumi este clube para me infiltrar no mercado negro na festa de grande inauguração.",
  ui_story_32180601_1_93_dialog_content = "Se as pessoas descobrirem que eu assumi este clube...",
  ui_story_32180601_1_94_dialog_content = "Parecerá que estou tentando invadir o território deles. É muito óbvio, você não acha? Ninguém vai aparecer.",
  ui_story_32180601_1_95_dialog_content = "Exatamente como eu esperaria de você, muito perspicaz mesmo.",
  ui_story_32180601_1_96_dialog_content = "O que mais eu poderia fazer? Pode se tornar a festa de abertura mais silenciosa da história de Umbraton...",
  ui_story_32180601_1_97_dialog_content = "... Apenas mantenha em segredo que você comprou, isso não está bem?",
  ui_story_32180601_1_98_dialog_content = "A rede de inteligência em Umbraton é mais sofisticada do que você imagina. A notícia da aquisição do clube por um comprador anônimo foi disseminada.",
  ui_story_32180601_1_99_dialog_content = "Com tanto em jogo nisso, não é surpresa que as pessoas estejam começando a especular sobre quem comprou o lugar.",
  ui_story_32180601_1_100_dialog_content = "A preocupação mais urgente neste momento é garantir um comprador legítimo para mitigar especulações externas desnecessárias.",
  ui_story_32180601_1_101_dialog_content = "Então, quem seria o comprador mais adequado para enviar convites aos líderes de todas as guildas em Umbraton?",
  ui_story_32180601_1_102_dialog_content = "...Eu?",
  ui_story_32180601_1_103_dialog_content = "Você realmente entende minhas intenções.",
  ui_story_32180601_1_104_dialog_content = "Então essa é a sua razão para me dar o clube...",
  ui_story_32180601_1_105_dialog_content = "Mas não é impecável, não é?",
  ui_story_32180601_1_106_dialog_content = "Por exemplo, eu sou o Celestita... Não é bastante óbvio?",
  ui_story_32180601_1_107_dialog_content = "E isso não parece certo... Quer dizer, meus ancestrais chorariam se soubessem que eu possuo um clube assim.",
  ui_story_32180601_1_108_dialog_content = "Então, ainda deveríamos...",
  ui_story_32180601_1_109_dialog_content = "Oh querido, você não vai dizer não, vai?",
  ui_story_32180601_1_110_dialog_content = "Uh, talvez devêssemos planejar as coisas?",
  ui_story_32180601_1_111_dialog_content = "Não há tempo para isso. Os convites foram preparados e estão aguardando sua aprovação para distribuição.",
  ui_story_32180601_1_112_dialog_content = "Claro, em seu nome.",
  ui_story_32180601_1_113_dialog_content = "Em meu nome?!",
  ui_story_32180601_1_114_dialog_content = "Eu não acho que alguém iria acreditar na minha história, as guildas ou o chefe do mercado negro.",
  ui_story_32180601_1_115_dialog_content = "Não, não, minha querida, você realmente não sabe nada sobre o seu charme.",
  ui_story_32180601_1_116_dialog_content = "Você é o único indivíduo capaz de unificar as facções dispersas de Astra.",
  ui_story_32180601_1_117_dialog_content = "Apenas você pode preencher a lacuna entre esses líderes desconfiados.",
  ui_story_32180601_1_118_dialog_content = "Sem mencionar, você é um parceiro importante para o Senhor Sombrio. Isso não é segredo.",
  ui_story_32180601_1_119_dialog_content = "A Guilda Umbraton?! De fato... é uma grande coincidência...",
  ui_story_32180601_1_120_dialog_content = "Com sua visão positiva, otimismo e influência incomparável em todo o Astra...",
  ui_story_32180601_1_121_dialog_content = "Quando você quer estabelecer um clube em Umbraton para coletar informações, negociar mercadorias e hospedar reuniões para os líderes...",
  ui_story_32180601_1_122_dialog_content = "Quem se atreveria a dizer não para você?",
  ui_story_32180601_1_123_dialog_content = "Você quase me convenceu...",
  ui_story_32180601_1_124_dialog_content = "Não se preocupe. Se alguém tentar mexer com você, estou com você.",
  ui_story_32180601_1_125_dialog_content = "Farei o meu máximo para te apoiar e proteger, meu querido.",
  ui_story_32180601_1_126_dialog_content = "Confie em mim, trabalhe comigo, e ambos sairemos beneficiados.",
  ui_story_32180601_1_127_dialog_content = "Tá bom.",
  ui_story_32180601_1_128_dialog_content = "Tudo bem, eu vou apenas assinar o acordo.",
  ui_story_32180601_1_129_dialog_content = "Ótima decisão! Essa é uma oportunidade de ouro para nós dois.",
  ui_story_32180601_1_130_dialog_content = "Certo, seu plano realmente me impressionou, isso é certo.",
  ui_story_32180601_1_131_dialog_content = "O que é mais importante... Eu acredito em você.",
  ui_story_32180601_1_132_dialog_content = "Investir em você certamente vale alguma coisa, certo?",
  ui_story_32180601_1_133_dialog_content = "Humph, claro.",
  ui_story_32180601_1_134_dialog_content = "Espero que você entenda, somos mais do que apenas parceiros de negócios.",
  ui_story_32180601_1_135_dialog_content = "Estou ansioso para ver seu desempenho na festa de abertura...",
  ui_story_32180601_1_136_dialog_content = "<color=#e8d9bb>E aqui estou eu, na festa de abertura, esperando ansiosamente...</color>",
  ui_story_32180601_1_137_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_32180601_1_138_dialog_content = "Hmm? Então você é o novo dono do clube?",
  ui_story_32180601_1_139_dialog_content = "Não é apenas um novato? Ele realmente pode ser o curador aqui?",
  ui_story_32180601_1_140_dialog_content = "Não me diga que você está planejando abrir uma creche aqui?",
  ui_story_32180601_1_141_dialog_content = "Hahahahaha!",
  ui_story_32180601_1_142_dialog_content = "(Fiz alguns inimigos em Umbraton, então acho que isso era inevitável...)",
  ui_story_32180601_1_143_dialog_content = "(No entanto, este é o primeiro dia de negócios; eu não posso estragar tudo!)",
  ui_story_32180601_1_144_dialog_content = "(Eu tenho que ajudar a Senhora Sheol...)",
  ui_story_32180601_1_145_dialog_content = "*tosse* Vocês dois, sabem com quem estão falando?",
  ui_story_32180601_1_146_dialog_content = "Hã? Como ousa falar comigo assim em Umbraton. Diga isso de novo e eu vou virar este lugar de cabeça para baixo.",
  ui_story_32180601_1_147_dialog_content = "Se tentar qualquer coisa, vai se arrepender. Você não vai sair daqui vivo.",
  ui_story_32180601_1_148_dialog_content = "O que você disse?!",
  ui_story_32180601_1_149_dialog_content = "Desculpe, estou atrasado, Sr. Navegador.",
  ui_story_32180601_1_150_dialog_content = "...?!",
  ui_story_32180601_1_151_dialog_content = "Que falta de educação da minha parte chegar atrasado em uma ocasião tão importante!",
  ui_story_32180601_1_152_dialog_content = "Por favor, certifique-se de aceitar o presente da Guilda Cloudrover.",
  ui_story_32180601_1_153_dialog_content = "É isso... um cheque da Guilda Cloudrover? E quantos zeros tem isso?!",
  ui_story_32180601_1_154_dialog_content = "Devo pagar tanto a ele por proteção?",
  ui_story_32180601_1_155_dialog_content = "Minha oferta é uma fração minúscula do que uma expedição conjunta custaria. Espero que você aceite mesmo assim.",
  ui_story_32180601_1_156_dialog_content = "Tudo o que peço é que você reconheça o patrocínio da Guilda Cloudrover ao discutir assuntos de importância com o Grande Marechal ou Shadowlord.",
  ui_story_32180601_1_157_dialog_content = "Seria minha maior honra.",
  ui_story_32180601_1_158_dialog_content = "Espere, Senhora Sheol, está dizendo que ele está ligado à expedição conjunta...?",
  ui_story_32180601_1_159_dialog_content = "Esse cara não está apenas contando com suas conexões com a sede e aqueles fãs loucos? Os Lovegators?",
  ui_story_32180601_1_160_dialog_content = "Vocês dois estão fazendo bastante barulho desde mais cedo...",
  ui_story_32180601_1_161_dialog_content = "O novo curador não gosta de barulho, acho que é hora de pedir para você sair...",
  ui_story_32180601_1_162_dialog_content = "Não queremos aborrecer o curador e estragar o negócio para todos.",
  ui_story_32180601_1_163_dialog_content = "Por favor, faça o seu caminho de volta!",
  ui_story_32180601_1_164_dialog_content = "Ouvi dizer que o Senhor Sombrio também quer conhecer o novo curador.",
  ui_story_32180601_1_165_dialog_content = "Ei, espere um minuto, como poderíamos estar aqui para causar problemas!",
  ui_story_32180601_1_166_dialog_content = "Se o Senhor Sombrio realmente nos agraciar com sua presença... Por favor, deixe-me fazer um investimento!",
  ui_story_32180601_1_167_dialog_content = "I-Igualmente! Se houver uma chance de trabalhar com a Illumina, eu definitivamente estou interessado.",
  ui_story_32180601_1_168_dialog_content = "O que você está esperando? Vá pegar um lugar!",
  ui_story_32180601_1_169_dialog_content = "O que está acontecendo... Hã?!",
  ui_story_32180601_1_170_dialog_content = "<color=#e8d9bb>Assim, a festa de abertura tornou-se uma cerimônia de assinatura.</color>",
  ui_story_32180601_1_171_dialog_content = "<color=#e8d9bb>E os contratos assinados em apenas meio dia representam uma quantidade de dinheiro sem precedentes...</color>",
  ui_story_32180601_1_172_dialog_content = "Ufa... Está me matando...",
  ui_story_32180601_1_173_dialog_content = "Você se superou! Estou te vendo sob uma luz completamente nova.",
  ui_story_32180601_1_174_dialog_content = "Não seja tão fácil em seu julgamento. Acho que havia vários acordos acontecendo.",
  ui_story_32180601_1_175_dialog_content = "Eu estava te dando sinais, mas tudo que você fez foi fumar seu cachimbo e me instigar a assinar. Se algo der errado, não venha chorar para mim!",
  ui_story_32180601_1_176_dialog_content = "Sem problemas, tudo que você precisa fazer é assiná-los. Eu tenho muito mais para considerar.",
  ui_story_32180601_1_177_dialog_content = "Fique tranquilo, eu posso lidar perfeitamente com a maioria dos negócios; são apenas alguns.",
  ui_story_32180601_1_178_dialog_content = "Talvez esteja um pouco fora de controle.",
  ui_story_32180601_1_179_dialog_content = "Então... a gangue não viria atrás de mim para causar problemas?!",
  ui_story_32180601_1_180_dialog_content = "Não, não, eu desisto. Escolha outra pessoa para o curador!",
  ui_story_32180601_1_181_dialog_content = "Oh não, isso não vai funcionar. Até você precisa aderir ao espírito do contrato.",
  ui_story_32180601_1_182_dialog_content = "Além disso, você não acabou de vivenciar isso agora mesmo?",
  ui_story_32180601_1_183_dialog_content = "A vida dos ricos? Estou bem como um celestita!",
  ui_story_32180601_1_184_dialog_content = "Não foi isso que eu quis dizer, eu estava falando sobre os serviços de segurança da Guilda Cloudrover.",
  ui_story_32180601_1_185_dialog_content = "Por favor, faça o seu caminho de volta.",
  ui_story_32180601_1_186_dialog_content = "Tudo que você precisa fazer é fechar mais um negócio comigo, e os serviços de segurança da Guilda Cloudrover serão gratuitos para você para sempre!",
  ui_story_32180601_1_187_dialog_content = "Mas... eu me recuso!",
  ui_story_32180601_1_188_dialog_content = "Você é tão tímido quanto sempre, não é, minha querida...",
  ui_story_32180601_1_189_dialog_content = "No entanto, como você assinou tantos contratos hoje, algumas pessoas podem inevitavelmente ficar com ciúmes. Seria melhor ficar no clube e descansar bem.",
  ui_story_32180601_1_190_dialog_content = "Sair de Umbraton no meio da noite não é seguro. Há uma grande chance de você ser sequestrado.",
  ui_story_32180601_1_191_dialog_content = "Você nunca mencionou que havia tal risco antes!?",
  ui_story_32180601_1_192_dialog_content = "Você nunca ficaria aqui se eu te contasse. Tenho medo que você já teria fugido com seu Colossus invejável.",
  ui_story_32180601_1_193_dialog_content = "Então, permita-me cuidar bem de você esta noite e experimente um ótimo banho!",
  ui_story_32180601_1_194_dialog_content = "Ahn? Ah? O que—!!!"
}
return config
